// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address target, bool status) public {
        vm.assume(caller != address(this)); // owner is address(this) by default
        vm.assume(target != address(0));

        bool initialStatus = c.approvedLoggers(target);

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setApprovedLogger(address,bool)", target, status));

        // In reference, only owner can change mapping; in mutant, no one can
        // So the rule: if caller is not owner, mapping doesn't change
        bool finalStatus = c.approvedLoggers(target);
        assertTrue(finalStatus == initialStatus, "Non-owner should not be able to change approvedLoggers");
    }
}

